(()=>{const back=label=>`<button class="back" id="panel-back">← ${label}</button>`;function bindBack(){document.querySelector('#panel-back').onclick=()=>{view='home';selected=null;render();};}function branches(){const rows=(data.settings.branches||[]).map(x=>`${x.name}|${x.latitude}|${x.longitude}`).join('\n');app.innerHTML=`${back('Owner dashboard')}<section class="card focus-panel"><div class="eyebrow">OWNER TOOLS</div><h1>Service branches</h1><p class="muted">Only these branches appear to customers. One per line: Branch name | latitude | longitude.</p><form id="focused-branches"><label class="field">Branches<textarea name="branches" required>${esc(rows)}</textarea></label><button class="primary">Save branches</button></form></section>`;bindBack();document.querySelector('#focused-branches').onsubmit=e=>{e.preventDefault();const list=new FormData(e.target).get('branches').split('\n').map(x=>x.split('|').map(y=>y.trim())).filter(x=>x.length===3&&x[0]).map(([name,latitude,longitude])=>({id:name.toLowerCase().replace(/[^a-z0-9]+/g,'-'),name,latitude:Number(latitude),longitude:Number(longitude)}));act('settings',{...data.settings,areas:data.settings.areas,branches:list});};}
 function detail(){const ticket=data.bookings.find(x=>x.id===selected);if(!ticket){view='tickets';render();return;}const techs=(data.technicians||[]).filter(x=>x.skills.includes(ticket.service));app.innerHTML=`${back('All tickets')}<section class="card focus-panel"><div class="eyebrow">TICKET ${esc(ticket.id)}</div><h1>${esc(svc(ticket.service).en)}</h1><p>${esc(ticket.issue)}</p><div class="ticket-details"><p><b>Customer</b><br>${esc(ticket.name)} · ${esc(ticket.phone)}</p><p><b>Address</b><br>${esc(ticket.village)} · ${esc(ticket.pin)}<br>${esc(ticket.landmark)}</p><p><b>Status</b><br>${esc(status(ticket))}</p></div>${['requested','assigned'].includes(ticket.status)?`<label class="field">${ticket.technicianId?'Reassign technician':'Assign technician'}<select id="detail-tech">${techs.map(x=>`<option value="${x.id}" ${x.id===ticket.technicianId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><button class="primary" id="detail-assign">${ticket.technicianId?'Save reassignment':'Save assignment'}</button>`:''}${!['completed','cancelled','declined'].includes(ticket.status)?'<button class="danger" id="close-ticket">Close ticket</button>':''}</section>`;bindBack();document.querySelector('#detail-assign')?.addEventListener('click',async()=>{const saved=await act('assign',{id:ticket.id,technicianId:document.querySelector('#detail-tech').value});if(saved){view='tickets';render();}});document.querySelector('#close-ticket')?.addEventListener('click',()=>act('close',{id:ticket.id}));}
 function tech(){const jobs=data.bookings||[],pending=jobs.filter(x=>!['completed','cancelled','declined'].includes(x.status)),done=jobs.filter(x=>x.status==='completed'),reviews=done.filter(x=>x.rating),rating=reviews.length?(reviews.reduce((sum,x)=>sum+x.rating,0)/reviews.length).toFixed(1):'—',total=jobs.length||1;app.innerHTML=`<div class="intro"><div><div class="eyebrow">TECHNICIAN DASHBOARD</div><h1>${esc(localUser.name)}</h1><p>Your assigned work, customer reviews and productivity.</p></div></div><div class="stats tech-stats"><div class="stat">Assigned tickets<b>${jobs.length}</b></div><div class="stat">Pending tasks<b>${pending.length}</b></div><div class="stat">Completed<b>${done.length}</b></div><div class="stat">Customer rating<b>${rating}</b></div></div><section class="card focus-panel"><h2>Productivity</h2><div class="productivity"><span style="width:${Math.round(done.length/total*100)}%"></span></div><p class="muted">${done.length} of ${jobs.length} assigned tickets completed.</p><h3>Pending tasks</h3>${pending.length?pending.map(x=>`<button class="ticket-row" data-tech-ticket="${x.id}"><span><strong>${esc(svc(x.service).en)}</strong><small>${esc(x.village)} · ${esc(x.id)}</small></span><span class="ticket-status progress">${esc(status(x))}</span></button>`).join(''):'<p class="muted">No pending tasks.</p>'}</section>`;app.querySelectorAll('[data-tech-ticket]').forEach(b=>b.onclick=()=>{selected=b.dataset.techTicket;view='home';render();});}
 const baseRender=render;render=function(){baseRender();if(!localToken||!data)return;if(role==='admin'&&view==='owner-branches')branches();else if(role==='admin'&&view==='ticket-detail')detail();else if(role==='technician'&&view==='home')tech();};})();
